 "content": "from collections import Counter

def transform(grid):
    """Copy the rare colored silhouette onto every all-zero matching position."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    colors = [v for v, n in counts.items() if v != 0 and n < h*w//4]
    if not colors:
        return g
    color = min(colors, key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
    minr = min(r for r,c in points); maxr = max(r for r,c in points)
    minc = min(c for r,c in points); maxc = max(c for r,c in points)
    shape = [(r-minr, c-minc) for r,c in points]
    sh, sw = maxr-minr+1, maxc-minc+1
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(g[r+dr][c+dc] == 0 for dr,dc in shape):
                for dr,dc in shape:
                    g[r+dr][c+dc] = color
    return g
